/// The production for nonterminal `nt` on terminal `term`, or -1.
#[inline]
pub fn action(nt: u16, term: u16) -> i16 {
    TABLE[nt as usize * NTERM + term as usize]
}

/// Production `prod`'s right-hand side, reversed (push order).
#[inline]
pub fn rhs_rev(prod: u16) -> &'static [u16] {
    &PROD_RHS[PROD_OFF[prod as usize] as usize..PROD_OFF[prod as usize + 1] as usize]
}
